-- The net-weight check is weighed at packing: FRM-520 v2, FSQM-020 v4, FSQM-021 v2.
--
-- Owner's decision, 2026-10-12. FSQM-020 had the SQF Practitioner weigh three finished packs at release
-- and write the weights on the release record (FRM-701). The packs are now weighed where the lot is
-- packed, by production staff, and recorded on the Production Lot Record:
--   - FRM-520 New -> v2: Section 3 gains Net weight on the label, Empty packaging weight, Unit
--     weighed in, and Pack 1 / 2 / 3 weight, all required, before Notes.
--   - FSQM-020 v3 -> v4: the net-weight line says the packs were weighed at packing and are on
--     FRM-520, with a paragraph on who weighs and what happens to a short weight. Linked forms and
--     Records name FRM-520.
--   - FSQM-021 New -> v2: the packing Part gains the weighing line; Records names the weights.
-- FRM-701 is NOT revised: it keeps its weight fields, which the release helper now fills from the
-- lot record. The SQF Practitioner still confirms the result and release is still theirs alone.
--
-- Approved by GJM, effective 2026-10-12. No FRM-520 entry was an open draft when this was written.
--
-- Safe to run twice: a document already as intended is left alone, so no second history snapshot
-- is taken. Any other shape stops the migration.

do $$
declare
  d record;
  n int;
  sec_old constant jsonb := $a1${"id": "packing", "title": "3. Packing", "fields": [{"id": "pack_date", "help": "If packing ran over two days, the first day - note the second below", "type": "date", "label": "Packed on", "width": "third", "required": true}, {"id": "racked_count", "min": 0, "help": "The count taken when the cakes went on the rack.", "type": "number", "label": "Counted on the baking rack", "width": "third", "required": true}, {"id": "units_packed", "type": "text", "label": "Units packed", "width": "third", "required": true}, {"id": "not_packed", "min": 0, "help": "Broken at depanning, too big or too small, oversoaked, otherwise rejected or damaged, or kept as the retention sample. Write 0 if none.", "type": "number", "label": "Not packed", "width": "third", "required": true}, {"id": "film_lot", "help": "The lot printed on the film roll or bag case. If none is printed, write \"no lot - received\" and the date it was received. Boxes need nothing.", "type": "text", "label": "Film / bag lot", "width": "third", "required": false}, {"id": "code_check", "help": "Look at the first pack at the start, and again after every change of product or new roll of film: the flavor or variety (on printed film, that it is the film for this variety), the lot code, the best-by date, and that any bar code scans (FSQM-021).", "type": "select", "label": "Code on the pack", "options": ["Matches the lot code above", "Did not match - held on FRM-702"], "required": true}, {"id": "code_checked_by", "help": "The name of the person who checked and approved the first pack.", "type": "text", "label": "First pack checked by", "required": true, "teamPick": {}, "maxLength": 120}, {"id": "packing_notes", "help": "If the rack count does not equal units packed plus not packed, say why here.", "type": "textarea", "label": "Notes"}]}$a1$::jsonb;
  sec_new constant jsonb := $a2${"id": "packing", "title": "3. Packing", "fields": [{"id": "pack_date", "help": "If packing ran over two days, the first day - note the second below", "type": "date", "label": "Packed on", "width": "third", "required": true}, {"id": "racked_count", "min": 0, "help": "The count taken when the cakes went on the rack.", "type": "number", "label": "Counted on the baking rack", "width": "third", "required": true}, {"id": "units_packed", "type": "text", "label": "Units packed", "width": "third", "required": true}, {"id": "not_packed", "min": 0, "help": "Broken at depanning, too big or too small, oversoaked, otherwise rejected or damaged, or kept as the retention sample. Write 0 if none.", "type": "number", "label": "Not packed", "width": "third", "required": true}, {"id": "film_lot", "help": "The lot printed on the film roll or bag case. If none is printed, write \"no lot - received\" and the date it was received. Boxes need nothing.", "type": "text", "label": "Film / bag lot", "width": "third", "required": false}, {"id": "code_check", "help": "Look at the first pack at the start, and again after every change of product or new roll of film: the flavor or variety (on printed film, that it is the film for this variety), the lot code, the best-by date, and that any bar code scans (FSQM-021).", "type": "select", "label": "Code on the pack", "options": ["Matches the lot code above", "Did not match - held on FRM-702"], "required": true}, {"id": "code_checked_by", "help": "The name of the person who checked and approved the first pack.", "type": "text", "label": "First pack checked by", "required": true, "teamPick": {}, "maxLength": 120}, {"id": "net_weight_info", "type": "info", "label": "Net weight", "text": "Weigh three finished packs from this lot, each one whole, on a scale that is in the calibration program (FSQM-030). With the empty packaging taken off, their average must be at or above the net weight on the label (FSQM-020). If it is not, stop packing, hold the lot on FRM-702 and tell the SQF Practitioner."}, {"id": "net_weight_declared", "type": "text", "label": "Net weight on the label", "width": "third", "required": true, "maxLength": 60, "help": "As printed on the pack, with its unit - from the product's specification (FRM-704)."}, {"id": "packaging_tare", "type": "number", "label": "Empty packaging weight", "min": 0, "width": "third", "required": true, "help": "The empty pouch, baking cup and box together, in the unit weighed in."}, {"id": "net_weight_unit", "type": "select", "label": "Unit weighed in", "options": ["oz", "g", "lb"], "width": "third", "required": true}, {"id": "pack_weight_1", "type": "number", "label": "Pack 1 weight", "min": 0, "width": "third", "required": true, "help": "The whole finished pack, as weighed."}, {"id": "pack_weight_2", "type": "number", "label": "Pack 2 weight", "min": 0, "width": "third", "required": true}, {"id": "pack_weight_3", "type": "number", "label": "Pack 3 weight", "min": 0, "width": "third", "required": true}, {"id": "packing_notes", "help": "If the rack count does not equal units packed plus not packed, say why here.", "type": "textarea", "label": "Notes"}]}$a2$::jsonb;
  h520 constant jsonb := $a3$"v2 - 2026-10-12 - Three finished packs are weighed at packing.\n\nSection 3 gains the net-weight block before Notes: Net weight on the label, Empty packaging weight, Unit weighed in, and Pack 1, 2 and 3 weight, all required. Until now the three packs were weighed by the SQF Practitioner at release and written only on the release record (FRM-701). They are now weighed where the lot is packed, by production staff, so a short weight is found while the lot is still on the table (owner's decision, 2026-10-12; FSQM-020 v4, FSQM-021 v2). The release record takes the weights from this record. Nothing else on the form changes."$a3$::jsonb;
  p020_old constant jsonb := $b1$["No finished product shall be made available for collection, or leave the site, until it has been released under this procedure.", "> Release is a decision, not a status that arrives by default. Product that has been made, packed and palletised is not released product until someone has checked it and said so on FRM-701.", "Release is authorised by the SQF Practitioner alone. No other role may release finished product.", "> SQF 2.4.7.1 requires release by authorised personnel. Here that is one person. Naming a second signature that does not exist would be a control in name only, and an auditor would test the separation of duties it implied.", "Product is released by batch or lot. Every release is recorded on FRM-701 Finished Product Release Record, one record per batch or lot.", "Before releasing a batch the SQF Practitioner shall confirm each of the following and record the result of each on FRM-701:", "• The batch sheet is complete and signed, and the formula, process steps and process controls were followed as specified.", "• The pre-operation and sanitation release for the line that produced the batch is recorded on FRM-903.", "• Neither the batch nor any ingredient in it is on Hold under FSQM-018, and no hold tag applies to it.", "• The label applied is the approved label for that product and that customer, verified against REP-602 Approved Label Register, and its allergen statement and any Gluten Free claim are correct for what was actually run.", "• The pack, the seal and the package integrity are correct for the specification.", "• The date and lot code are present, legible and correct.", "• A unit taken from the batch meets the product's appearance and sensory standard on examination.", "• The quantity and pack configuration match the customer's agreed specification.", "• Three finished packs taken from the batch are weighed on a scale that is in the calibration program (FSQM-030). With the weight of the empty packaging taken off, the average of the three is at or above the net weight declared on the label. The weights are recorded on FRM-701 (SQF 2.4.1.1).", "The site does not use positive release based on pathogen or chemical testing. No finished product is sent for laboratory testing before shipment, and none is held pending a result.", "> This is stated rather than left silent because SQF 2.4.7.3 applies only where such testing gates release, and a document that implies a testing gate it does not operate is worse than one that says plainly there is none.", "> If finished-product testing is ever introduced, this procedure shall be revised before that product ships, so that the hold-pending-result step exists before it is needed rather than after.", "Before a product's first release, and again whenever its label changes, the SQF Practitioner shall confirm that the label complies with the food law of the country of manufacture and, where it is known, of the country of sale.", "> The label control system does this work: labels are approved under SOP-2.3.2.3 Label Control on FRM-601, the approved version is held on REP-602 and changes are tracked on REP-603. This program does not repeat it. The release check confirms that the label actually applied is the approved one; this Part confirms that the approved one is lawful.", "> All finished product leaves the site labelled and in its finished pack. The site supplies no product in bulk or unlabeled, so the requirement in the second half of SQF 2.4.7.2 — that product information be made available to inform customers or consumers of the requirements for safe use — does not arise.", "The site does not use off-site or contract warehouses. Finished product is collected from the site by a carrier the customer arranges, and responsibility for the product passes to the customer on collection.", "> SQF 2.4.7.3 requires release requirements to be communicated to off-site or contract warehouses and verified as being followed, where such warehouses are used. They are not used here, so that requirement does not arise. This is stated rather than left silent, for the same reason Part 5 states that positive release on testing is not used: a reader should not have to work out for themselves which limbs of a clause apply to this site.", "> What collection does change is the timing. Release has to be complete before the carrier arrives, not while it waits on the dock. Once product is loaded it has left, and a release recorded afterwards records nothing.", "If any check fails, the batch shall not be released. It shall be placed on Hold under FSQM-018 Non-Conforming Product and Equipment, recorded on FRM-702, and dispositioned there.", "> A batch that fails a release check is non-conforming product. The release record ends at \"not released\" and the hold record takes over. A CAPA is raised under FSQM-009 where its Part 3 requires one.", "Released product may then be made available for collection. FRM-701 shall be completed and signed before that happens, not afterwards.", "Records are retained as set out in the Records section of this program."]$b1$::jsonb;
  p020_new constant jsonb := $b2$["No finished product shall be made available for collection, or leave the site, until it has been released under this procedure.", "> Release is a decision, not a status that arrives by default. Product that has been made, packed and palletised is not released product until someone has checked it and said so on FRM-701.", "Release is authorised by the SQF Practitioner alone. No other role may release finished product.", "> SQF 2.4.7.1 requires release by authorised personnel. Here that is one person. Naming a second signature that does not exist would be a control in name only, and an auditor would test the separation of duties it implied.", "Product is released by batch or lot. Every release is recorded on FRM-701 Finished Product Release Record, one record per batch or lot.", "Before releasing a batch the SQF Practitioner shall confirm each of the following and record the result of each on FRM-701:", "• The batch sheet is complete and signed, and the formula, process steps and process controls were followed as specified.", "• The pre-operation and sanitation release for the line that produced the batch is recorded on FRM-903.", "• Neither the batch nor any ingredient in it is on Hold under FSQM-018, and no hold tag applies to it.", "• The label applied is the approved label for that product and that customer, verified against REP-602 Approved Label Register, and its allergen statement and any Gluten Free claim are correct for what was actually run.", "• The pack, the seal and the package integrity are correct for the specification.", "• The date and lot code are present, legible and correct.", "• A unit taken from the batch meets the product's appearance and sensory standard on examination.", "• The quantity and pack configuration match the customer's agreed specification.", "• Three finished packs taken from the batch were weighed at packing, on a scale that is in the calibration program (FSQM-030), and the weights are on the Production Lot Record (FRM-520). With the weight of the empty packaging taken off, the average of the three is at or above the net weight declared on the label. The weights are carried onto FRM-701 (SQF 2.4.1.1).", "> The packs are weighed by production staff where the lot is packed, not at release, so a short weight is found while the lot is still on the packing table. A lot whose average is below the label is held under FSQM-018 on FRM-702 until the SQF Practitioner decides. At release the SQF Practitioner confirms the result from the weights recorded; the decision to release is still theirs alone.", "The site does not use positive release based on pathogen or chemical testing. No finished product is sent for laboratory testing before shipment, and none is held pending a result.", "> This is stated rather than left silent because SQF 2.4.7.3 applies only where such testing gates release, and a document that implies a testing gate it does not operate is worse than one that says plainly there is none.", "> If finished-product testing is ever introduced, this procedure shall be revised before that product ships, so that the hold-pending-result step exists before it is needed rather than after.", "Before a product's first release, and again whenever its label changes, the SQF Practitioner shall confirm that the label complies with the food law of the country of manufacture and, where it is known, of the country of sale.", "> The label control system does this work: labels are approved under SOP-2.3.2.3 Label Control on FRM-601, the approved version is held on REP-602 and changes are tracked on REP-603. This program does not repeat it. The release check confirms that the label actually applied is the approved one; this Part confirms that the approved one is lawful.", "> All finished product leaves the site labelled and in its finished pack. The site supplies no product in bulk or unlabeled, so the requirement in the second half of SQF 2.4.7.2 — that product information be made available to inform customers or consumers of the requirements for safe use — does not arise.", "The site does not use off-site or contract warehouses. Finished product is collected from the site by a carrier the customer arranges, and responsibility for the product passes to the customer on collection.", "> SQF 2.4.7.3 requires release requirements to be communicated to off-site or contract warehouses and verified as being followed, where such warehouses are used. They are not used here, so that requirement does not arise. This is stated rather than left silent, for the same reason Part 5 states that positive release on testing is not used: a reader should not have to work out for themselves which limbs of a clause apply to this site.", "> What collection does change is the timing. Release has to be complete before the carrier arrives, not while it waits on the dock. Once product is loaded it has left, and a release recorded afterwards records nothing.", "If any check fails, the batch shall not be released. It shall be placed on Hold under FSQM-018 Non-Conforming Product and Equipment, recorded on FRM-702, and dispositioned there.", "> A batch that fails a release check is non-conforming product. The release record ends at \"not released\" and the hold record takes over. A CAPA is raised under FSQM-009 where its Part 3 requires one.", "Released product may then be made available for collection. FRM-701 shall be completed and signed before that happens, not afterwards.", "Records are retained as set out in the Records section of this program."]$b2$::jsonb;
  refs020_old constant jsonb := $b3$"FRM-701 Finished Product Release Record; FRM-702 Non-Conforming Material Hold & Tagging Record; FRM-903 Daily Sanitation, Pre-Operation & Release Record; FRM-601 Label Review & Approval Form; REP-602 Approved Label Register; batch sheets"$b3$::jsonb;
  refs020_new constant jsonb := $b4$"FRM-701 Finished Product Release Record; FRM-520 Production Lot Record; FRM-702 Non-Conforming Material Hold & Tagging Record; FRM-903 Daily Sanitation, Pre-Operation & Release Record; FRM-601 Label Review & Approval Form; REP-602 Approved Label Register; batch sheets"$b4$::jsonb;
  rec020_old constant jsonb := $b5$"FRM-701 Finished Product Release Record — one per batch or lot released, carrying every release check, the label verification, the release decision and the signature of the person who made it. This is the record of product release that SQF 2.4.7.1 and Quality Code 2.4.7.2 require.\nFRM-702 Non-Conforming Material Hold & Tagging Record — where a batch fails a release check and is held instead of released.\nFRM-903 Daily Sanitation, Pre-Operation & Release Record — the line release the batch was produced against.\nREP-602 Approved Label Register — the approved label the applied label is verified against.\nBatch sheets — the production record the release check reads.\nRetention: two years, or the shelf life of the product plus twelve months, whichever is longer. This is the period set by FSQM-009 Part 10, so a release, a hold arising from it and any investigation that follows are retained on the same basis."$b5$::jsonb;
  rec020_new constant jsonb := $b6$"FRM-701 Finished Product Release Record — one per batch or lot released, carrying every release check, the label verification, the release decision and the signature of the person who made it. This is the record of product release that SQF 2.4.7.1 and Quality Code 2.4.7.2 require.\nFRM-702 Non-Conforming Material Hold & Tagging Record — where a batch fails a release check and is held instead of released.\nFRM-903 Daily Sanitation, Pre-Operation & Release Record — the line release the batch was produced against.\nREP-602 Approved Label Register — the approved label the applied label is verified against.\nBatch sheets — the production record the release check reads.\nRetention: two years, or the shelf life of the product plus twelve months, whichever is longer. This is the period set by FSQM-009 Part 10, so a release, a hold arising from it and any investigation that follows are retained on the same basis.\nFRM-520 Production Lot Record — the three pack weights of the net-weight check, taken at packing and carried onto FRM-701."$b6$::jsonb;
  h020_old constant jsonb := $b7$"Rev New — written 2026-09-03 against SQF Food Safety Code: Food Manufacturing 2.4.7 Product Release, which is MANDATORY, and SQF Quality Code 2.4.7.1. DRAFT. Not approved, not in force.\n\nWHY IT EXISTS. FSQM-018 named a \"Positive Release Procedure\" as the authority for the final disposition of reworked material, and no document of that name existed anywhere in the register — a Compass Blending reference that survived the scan. That citation was removed on 2026-09-02 when FSQM-018 gained a release step of its own, but the gap underneath it was real: the site had no documented method for releasing finished product at all, against an element the Food Manufacturing code marks Mandatory.\n\nIT IS A PRODUCT RELEASE PROGRAM, NOT A POSITIVE RELEASE PROCEDURE, and the difference is deliberate. 2.4.7 has three limbs — release by authorised personnel after documented checks (2.4.7.1), confirmation that labels comply with food law (2.4.7.2), and positive release where testing gates it, plus off-site storage (2.4.7.3). A document written to the name FSQM-018 used would have closed the third limb and left the Mandatory element open.\n\nWHAT THE SITE ACTUALLY DOES, confirmed 2026-09-03. Before a batch ships, the batch sheet is reviewed, the label is checked, and the packaging and the product itself are looked at. That already covers most of what Quality Code 2.4.7.1 lists. This program writes down what is already done and adds only what the clause requires on top — a named authority, a record, and the off-site storage rule. It does not invent a control nobody performs, because a control nobody performs is a finding waiting to be made.\n\nNO POSITIVE RELEASE ON TESTING, AND THE DOCUMENT SAYS SO. No finished product is sent for laboratory testing before shipment and none is held pending a result. SQF 2.4.7.3 applies only where such testing gates release, so Part 5 states plainly that the practice is not used rather than leaving a reader to assume a gate exists. It also says what must happen before that changes: if finished-product testing is ever introduced — a gluten result for certified Gluten Free product being the likely first, since the site is GFCO certified — this procedure needs revising before that product ships, so the hold-pending-result step exists before it is needed rather than after.\n\nOFF-SITE STORAGE DOES NOT APPLY — CORRECTED 2026-09-04. This program was drafted on 2026-09-03 on the understanding that product went both from our own dock and into customer-owned or third-party storage, and Part 8 accordingly required a written instruction to each storage location, reissued on change and confirmed annually. The CEO and Operations Manager confirmed on 2026-09-04 that this is not how it works: the customer arranges collection with their own carrier, and responsibility for the product passes to the customer once it leaves the facility. The site uses no off-site or contract warehouse. Part 8 now says so, in the same form Part 5 uses for positive release on testing, and the written instruction it required — which was recorded here as a prerequisite to issue — is withdrawn as an open item because there is nobody to issue it to.\n\nWHAT THAT DOES NOT CHANGE, and it is worth saying because \"no longer our responsibility\" is easy to read more widely than it holds. Collection makes the timing of release SHARPER, not softer: the record has to be complete before the carrier arrives rather than before a transfer the site controls, because once product is loaded it has gone. And the passing of responsibility at the dock is a commercial fact about custody and risk, not a food-safety one — traceability, and any withdrawal or recall, still reach product after it has been collected. Neither is in this program's scope; both belong to the recall and withdrawal program, which does not yet exist.\n\nLABEL COMPLIANCE IS REFERENCED, NOT REPEATED. Labels are approved under SOP-2.3.2.3 on FRM-601, the approved version is held on REP-602, and changes are tracked on REP-603. Restating that here would create a second copy to drift, which is how FSQM-018 and FSQM-019 came to name different authorities for rework. The release check confirms that the label applied is the approved one; Part 6 confirms that the approved one is lawful.\n\nONE PERSON RELEASES. 2.4.7.1 requires release by authorised personnel, and here that is the SQF Practitioner alone. Naming a second signature that does not exist would be a control in name only.\n\nNO BULK OR UNLABELED PRODUCT, CONFIRMED 2026-09-04. The site was asked whether it ships any, because Part 7 required safe-use information to travel with such a consignment and a Part describing something that never happens is worse than no Part at all — it is the first thing an auditor tests and the first thing the floor learns to ignore. It ships none. Part 7 is therefore gone as a step and its clause limb is stated in prose under Part 6, with the labelling content it belongs with: all finished product leaves labelled and in its finished pack, so the second half of 2.4.7.2 does not arise. That is the same treatment Part 5 gives positive release on testing and Part 8 gives off-site storage — three limbs of 2.4.7 that do not apply here, each said so rather than left silent.\n\nISSUED 2026-09-04, approved GJM. Status active, revision New — a first issue, not a revision, so nothing is superseded and nothing is archived. FRM-701 Finished Product Release Record is activated in the SAME TRANSACTION: this program requires a release to be recorded on it, and an active procedure requiring a record that is not available is the finding this wave exists to close.\n\nSETTLED AT ISSUE. Both questions this document carried were answered by the site on 2026-09-04. It ships no bulk or unlabeled product, so Part 7 became a scope statement under Part 6. It uses no off-site or contract warehouse — the customer collects with their own carrier — so Part 8's written instruction, the one item that genuinely blocked issue, was withdrawn. Neither answer was assumed; both were asked for and given.\n\nWHAT ISSUING ADOPTS. Three limbs of 2.4.7 are stated as not applying here: positive release on pathogen or chemical testing (Part 5), off-site and contract warehouses (Part 8), and bulk or unlabeled supply (Part 6). Issuing this document adopts those three scope statements as the site's position. Each names what would have to change first — Part 5 in terms, and the other two by describing the practice they depend on — so none of them can quietly stop being true.\n\nSTILL OPEN AFTER ISSUE — one item, and it is not about this document:\n\n1. There is no documented product sampling, inspection and analysis method (SQF 2.4.4.1), and no finished product specification in the register beyond SOP-2.3.1 New Product and Specification Process. The release check reads \"the customer's agreed specification\" and \"the product's appearance and sensory standard\". Confirm where those live, because this procedure points at them and an auditor will follow the pointer.\n\n\nRev v2 — 2026-09-09, approved GJM. WITHDRAWS AN ASSERTION THAT WAS NEVER TRUE. Part 5 of Rev New explained that if finished-product testing were ever introduced, a gluten result would be the likely first \"since the site is GFCO certified\". The Managing Partner confirmed on 2026-09-09 that Adventure Bakery holds no current GFCO certification and has never produced a product carrying a Gluten Free claim. Part 5 now states the rule without the example: if finished-product testing is ever introduced, this procedure is revised before that product ships. Nothing else in the procedure changes, and the release check at Part 4 is deliberately untouched — it reads \"any Gluten Free claim\", which is conditional and stays correct whether or not the site ever makes one.\n\nThe Rev New wording above is left standing rather than edited out. This history is the record of what the site believed and when, and an issued document that once asserted something untrue is better shown being corrected than quietly amended. The same false assumption reached FSQM-018, which is corrected by 20260909000008; its likeliest source is the Compass Blending hardcopies these documents were scanned from, where the import rebrands the company name but cannot know the content belongs to another business.\n\nv3 — 2026-10-05 — Net weight check added to the release checks. Until now weight was checked only when the batter was deposited into the molds - before baking, and before the syrup - so the weight of the finished pack was not known. Three packs from each batch are now weighed at release and the weights recorded on FRM-701, which goes to v2 with the added row and fields. SQF 2.4.1.1 names net weight among the legal requirements finished product must meet when it is delivered, and that clause is added to this program's references."$b7$::jsonb;
  h020_new constant jsonb := $b8$"Rev New — written 2026-09-03 against SQF Food Safety Code: Food Manufacturing 2.4.7 Product Release, which is MANDATORY, and SQF Quality Code 2.4.7.1. DRAFT. Not approved, not in force.\n\nWHY IT EXISTS. FSQM-018 named a \"Positive Release Procedure\" as the authority for the final disposition of reworked material, and no document of that name existed anywhere in the register — a Compass Blending reference that survived the scan. That citation was removed on 2026-09-02 when FSQM-018 gained a release step of its own, but the gap underneath it was real: the site had no documented method for releasing finished product at all, against an element the Food Manufacturing code marks Mandatory.\n\nIT IS A PRODUCT RELEASE PROGRAM, NOT A POSITIVE RELEASE PROCEDURE, and the difference is deliberate. 2.4.7 has three limbs — release by authorised personnel after documented checks (2.4.7.1), confirmation that labels comply with food law (2.4.7.2), and positive release where testing gates it, plus off-site storage (2.4.7.3). A document written to the name FSQM-018 used would have closed the third limb and left the Mandatory element open.\n\nWHAT THE SITE ACTUALLY DOES, confirmed 2026-09-03. Before a batch ships, the batch sheet is reviewed, the label is checked, and the packaging and the product itself are looked at. That already covers most of what Quality Code 2.4.7.1 lists. This program writes down what is already done and adds only what the clause requires on top — a named authority, a record, and the off-site storage rule. It does not invent a control nobody performs, because a control nobody performs is a finding waiting to be made.\n\nNO POSITIVE RELEASE ON TESTING, AND THE DOCUMENT SAYS SO. No finished product is sent for laboratory testing before shipment and none is held pending a result. SQF 2.4.7.3 applies only where such testing gates release, so Part 5 states plainly that the practice is not used rather than leaving a reader to assume a gate exists. It also says what must happen before that changes: if finished-product testing is ever introduced — a gluten result for certified Gluten Free product being the likely first, since the site is GFCO certified — this procedure needs revising before that product ships, so the hold-pending-result step exists before it is needed rather than after.\n\nOFF-SITE STORAGE DOES NOT APPLY — CORRECTED 2026-09-04. This program was drafted on 2026-09-03 on the understanding that product went both from our own dock and into customer-owned or third-party storage, and Part 8 accordingly required a written instruction to each storage location, reissued on change and confirmed annually. The CEO and Operations Manager confirmed on 2026-09-04 that this is not how it works: the customer arranges collection with their own carrier, and responsibility for the product passes to the customer once it leaves the facility. The site uses no off-site or contract warehouse. Part 8 now says so, in the same form Part 5 uses for positive release on testing, and the written instruction it required — which was recorded here as a prerequisite to issue — is withdrawn as an open item because there is nobody to issue it to.\n\nWHAT THAT DOES NOT CHANGE, and it is worth saying because \"no longer our responsibility\" is easy to read more widely than it holds. Collection makes the timing of release SHARPER, not softer: the record has to be complete before the carrier arrives rather than before a transfer the site controls, because once product is loaded it has gone. And the passing of responsibility at the dock is a commercial fact about custody and risk, not a food-safety one — traceability, and any withdrawal or recall, still reach product after it has been collected. Neither is in this program's scope; both belong to the recall and withdrawal program, which does not yet exist.\n\nLABEL COMPLIANCE IS REFERENCED, NOT REPEATED. Labels are approved under SOP-2.3.2.3 on FRM-601, the approved version is held on REP-602, and changes are tracked on REP-603. Restating that here would create a second copy to drift, which is how FSQM-018 and FSQM-019 came to name different authorities for rework. The release check confirms that the label applied is the approved one; Part 6 confirms that the approved one is lawful.\n\nONE PERSON RELEASES. 2.4.7.1 requires release by authorised personnel, and here that is the SQF Practitioner alone. Naming a second signature that does not exist would be a control in name only.\n\nNO BULK OR UNLABELED PRODUCT, CONFIRMED 2026-09-04. The site was asked whether it ships any, because Part 7 required safe-use information to travel with such a consignment and a Part describing something that never happens is worse than no Part at all — it is the first thing an auditor tests and the first thing the floor learns to ignore. It ships none. Part 7 is therefore gone as a step and its clause limb is stated in prose under Part 6, with the labelling content it belongs with: all finished product leaves labelled and in its finished pack, so the second half of 2.4.7.2 does not arise. That is the same treatment Part 5 gives positive release on testing and Part 8 gives off-site storage — three limbs of 2.4.7 that do not apply here, each said so rather than left silent.\n\nISSUED 2026-09-04, approved GJM. Status active, revision New — a first issue, not a revision, so nothing is superseded and nothing is archived. FRM-701 Finished Product Release Record is activated in the SAME TRANSACTION: this program requires a release to be recorded on it, and an active procedure requiring a record that is not available is the finding this wave exists to close.\n\nSETTLED AT ISSUE. Both questions this document carried were answered by the site on 2026-09-04. It ships no bulk or unlabeled product, so Part 7 became a scope statement under Part 6. It uses no off-site or contract warehouse — the customer collects with their own carrier — so Part 8's written instruction, the one item that genuinely blocked issue, was withdrawn. Neither answer was assumed; both were asked for and given.\n\nWHAT ISSUING ADOPTS. Three limbs of 2.4.7 are stated as not applying here: positive release on pathogen or chemical testing (Part 5), off-site and contract warehouses (Part 8), and bulk or unlabeled supply (Part 6). Issuing this document adopts those three scope statements as the site's position. Each names what would have to change first — Part 5 in terms, and the other two by describing the practice they depend on — so none of them can quietly stop being true.\n\nSTILL OPEN AFTER ISSUE — one item, and it is not about this document:\n\n1. There is no documented product sampling, inspection and analysis method (SQF 2.4.4.1), and no finished product specification in the register beyond SOP-2.3.1 New Product and Specification Process. The release check reads \"the customer's agreed specification\" and \"the product's appearance and sensory standard\". Confirm where those live, because this procedure points at them and an auditor will follow the pointer.\n\n\nRev v2 — 2026-09-09, approved GJM. WITHDRAWS AN ASSERTION THAT WAS NEVER TRUE. Part 5 of Rev New explained that if finished-product testing were ever introduced, a gluten result would be the likely first \"since the site is GFCO certified\". The Managing Partner confirmed on 2026-09-09 that Adventure Bakery holds no current GFCO certification and has never produced a product carrying a Gluten Free claim. Part 5 now states the rule without the example: if finished-product testing is ever introduced, this procedure is revised before that product ships. Nothing else in the procedure changes, and the release check at Part 4 is deliberately untouched — it reads \"any Gluten Free claim\", which is conditional and stays correct whether or not the site ever makes one.\n\nThe Rev New wording above is left standing rather than edited out. This history is the record of what the site believed and when, and an issued document that once asserted something untrue is better shown being corrected than quietly amended. The same false assumption reached FSQM-018, which is corrected by 20260909000008; its likeliest source is the Compass Blending hardcopies these documents were scanned from, where the import rebrands the company name but cannot know the content belongs to another business.\n\nv3 — 2026-10-05 — Net weight check added to the release checks. Until now weight was checked only when the batter was deposited into the molds - before baking, and before the syrup - so the weight of the finished pack was not known. Three packs from each batch are now weighed at release and the weights recorded on FRM-701, which goes to v2 with the added row and fields. SQF 2.4.1.1 names net weight among the legal requirements finished product must meet when it is delivered, and that clause is added to this program's references.\n\nv4 — 2026-10-12 — The net-weight packs are weighed at packing. Approved GJM.\n\nThe three finished packs of the net-weight check were weighed by the SQF Practitioner at release and written on FRM-701. They are now weighed at packing by production staff and recorded on the Production Lot Record (FRM-520 v2), where a short weight is found while the lot can still be corrected or held; FRM-701 carries the same weights, taken from the lot record. The SQF Practitioner still confirms the result at release and release remains theirs alone (owner's decision, 2026-10-12). The check itself - three packs, the empty packaging taken off, the average at or above the label - is unchanged. Linked forms and Records name FRM-520."$b8$::jsonb;
  p021_old constant jsonb := $c1$["Identification at every stage", "• Receipt: every delivery is logged on FRM-301 with the supplier, the material, the supplier lot and the date received. Material that arrives without a readable lot code or label is held on FRM-702 until the supplier identifies it (SQF 2.6.1.1 i, 2.6.2.1 ii).", "• Storage: every ingredient, processing aid and packaging material stays in the bag, box, pail or roll it arrived in, with the supplier's label and lot, until it is used up. A part-used bag is closed and kept in its own bag. Nothing is decanted into another container (SQF 2.6.1.1 i).", "• Production: ingredients are weighed straight from their original containers, so the supplier lot is in front of the person using it. Batter is deposited in the run it is mixed for and is never stored (SQF 2.6.1.1 i).", "• Syrup made ahead of the day it is used is kept in a container labelled with what it is and the date it was made (SQF 2.6.1.1 i).", "• Baked product cooling on racks carries a rack card with the product and its lot code until it is wrapped (SQF 2.6.1.1 i).", "• Finished product: every pack is coded with the lot code and best-by date on the coder (SOP-603, SOP-604) and labelled to its specification on FRM-704 and to US labelling law. The label and code are checked before release on FRM-701 under FSQM-020 (SQF 2.6.1.1 ii).", "• Product put on hold is identified by its FRM-702 hold tag, and a retention sample by its FRM-703 entry, each carrying the lot code.", "• A cake is taken out of the run, without a tag, when it breaks at depanning, is plainly too big or too small after baking, or is oversoaked in the syrup. These are ordinary losses in production, not held product. Each is set aside from good product, counted, and included in the units not packed on FRM-520. The lot's retention sample may be taken from them - a cake that is too big or too small will do, an oversoaked one will not - or from good product. Whichever it is, the sample is soaked and sealed like the rest of the lot and logged on FRM-703. Cakes not kept as a sample leave as food waste under FSQM-037. The hold tag is for product whose safety or quality is in question, not for these.", "The lot code", "• The lot code is the last digit of the year and the three-digit day of the year on which the product was BAKED, for example 6272. It is the same code written on FRM-507 for that day's oven loads.", "• When wrapping runs into the next day, the coder is set to the bake day's code, not to the day of wrapping. A product baked on day 272 is 6272 whenever it is packed.", "• One lot is one product baked on one day. If the same product is baked on two days, it is two lots.", "The Production Lot Record - the cross reference", "• For each product baked each day, a Production Lot Record is kept on FRM-520 as the product is made - filled in directly in the Team Portal, or written on the printed prep sheet on the floor and entered within one working day (SQF 2.6.2.1 i).", "• The record carries the product, its lot code and the bake date, and a line for every ingredient used with the supplier lot printed on its container. If two lots of the same ingredient are used, both are written down.", "• Processing aids are listed like ingredients - in particular the pan spray, which contains soy - so that every allergen-bearing input can be traced back (SQF 2.8.1.8).", "• If rework is used, it is recorded with its own original lot code, so a lot made with rework traces back through the rework to its supplier lots (SQF 2.6.2.1 iii).", "• At wrapping, the record takes the pack date and the number of units packed. The film or vacuum bag touches the cake and is food-contact packaging: its lot is written when the maker prints one, and when none is printed the date that film was received is written instead, which FRM-301 ties to its supplier. The boxes the sealed cakes go into are outer packaging and are not traced (SQF 2.6.2.1 ii).", "• Whichever way it is filled in, the FRM-520 entry is the record. A photo of a paper prep sheet may be attached to it but is not required; a paper sheet that was used is kept with the batch records under SOP-2.2.3 (SQF 2.6.2.1).", "Start-up, changeover and the label", "> Every rum cake is packed in the same box. The ingredient list and the allergen statement are printed on that box and are the same for every flavor. What changes from one product to the next is what the coder prints on the box at packing: the company name, the flavor, the lot code, the best-by date and the bar code. Putting the right label on a product therefore means loading the right coder message.", "> Product wrapped in printed film - the biscotti - is different. Each variety has its own film, with its own ingredient list and allergen statement printed on it, and the coder adds only the lot code and the best-by date. There, putting the right label on the product means loading the right roll of film, and a wrong roll is a wrong allergen statement.", "• At the start of packing, and every time the product changes, the person packing loads the coder message for that product - and, where the product is wrapped in printed film, the roll for that variety - and makes one pack (SOP-603, SOP-604, SOP-605).", "• That first pack is checked against the Production Lot Record before packing carries on: the flavor or variety on the pack is the product being packed; on printed film, the film is the one for that variety, with its allergen statement; the lot code and best-by date are right; and any bar code scans. Production staff trained on the coder and the wrapper are authorized to approve it. The result and the name of the person who checked are written on FRM-520 (SQF 2.6.1.2, 2.8.1.9).", "• The check is made again whenever the coder is restarted or its message is edited, and whenever a new roll of film is loaded during the run.", "• Before the next product is packed, boxes already printed for the one before are taken off the packing table, the film of the variety before is taken off the wrapper and put back with its own kind, and any other packaging that belongs only to that product is removed (SQF 2.6.1.2).", "• No pre-printed label is issued by count, so what is reconciled is the product. The cakes are counted when they go on the baking rack. At the end of packing that count is compared with the units packed plus the units not packed - broken at depanning, the wrong size, oversoaked, otherwise rejected or damaged, or kept as the retention sample - and all three figures are written on FRM-520. A difference that cannot be explained is settled before the lot is released, and raised on FRM-007 if it cannot be (SQF 2.6.1.2).", "• A product goes into a printed box or a printed film only if the ingredients and allergens of its formula are the ones printed on it. That is checked on FRM-601 before a new or changed product is first packed, and the change is assessed first under FSQM-007 (SQF 2.8.1.9).", "• When a printed box, a printed film or a coder message is replaced, the old boxes or film are taken out of use, counted and disposed of under FSQM-037, and the old message is deleted from the coder. Both are noted on the FRM-601 for the new version (SQF 2.8.1.9).", "• The label and the code are looked at once more, by the SQF Practitioner, when the lot is released on FRM-701.", "Tracing", "• One step back: from a finished lot code, FRM-520 gives every supplier lot used, and FRM-301 gives the supplier and the date each was received (SQF 2.6.2.1 i, ii).", "• One step forward: from a finished lot code, FRM-801 gives every customer who collected it, how much and when (SQF 2.6.2.1 i).", "• From a supplier lot - for example a supplier's recall or allergen notice - the FRM-520 entries that list it give every finished lot it went into, and FRM-801 gives where those lots went (SQF 2.8.1.8).", "Testing the trace", "• At least once a year, the SQF Practitioner picks a finished lot and traces it both ways from the records alone: back to every supplier lot and its receipt on FRM-301, and forward to every customer on FRM-801 (SQF 2.6.2.1 iv).", "• The test passes when every input is traced to a supplier lot and a receipt, and the quantity packed is accounted for - collected by customers, still on site, retained on FRM-703, or disposed of on FRM-702. Any gap is raised as a CAPA on FRM-007 under FSQM-009.", "• The trace test is part of the annual product recall and withdrawal test and is reviewed with it (SQF 2.6.2.1 iv).", "Records", "• FRM-301, FRM-520, FRM-507, FRM-701 and FRM-801 are the trace records. They are kept for at least two years, as SOP-2.2.3 requires (SQF 2.6.2.1)."]$c1$::jsonb;
  p021_new constant jsonb := $c2$["Identification at every stage", "• Receipt: every delivery is logged on FRM-301 with the supplier, the material, the supplier lot and the date received. Material that arrives without a readable lot code or label is held on FRM-702 until the supplier identifies it (SQF 2.6.1.1 i, 2.6.2.1 ii).", "• Storage: every ingredient, processing aid and packaging material stays in the bag, box, pail or roll it arrived in, with the supplier's label and lot, until it is used up. A part-used bag is closed and kept in its own bag. Nothing is decanted into another container (SQF 2.6.1.1 i).", "• Production: ingredients are weighed straight from their original containers, so the supplier lot is in front of the person using it. Batter is deposited in the run it is mixed for and is never stored (SQF 2.6.1.1 i).", "• Syrup made ahead of the day it is used is kept in a container labelled with what it is and the date it was made (SQF 2.6.1.1 i).", "• Baked product cooling on racks carries a rack card with the product and its lot code until it is wrapped (SQF 2.6.1.1 i).", "• Finished product: every pack is coded with the lot code and best-by date on the coder (SOP-603, SOP-604) and labelled to its specification on FRM-704 and to US labelling law. The label and code are checked before release on FRM-701 under FSQM-020 (SQF 2.6.1.1 ii).", "• Product put on hold is identified by its FRM-702 hold tag, and a retention sample by its FRM-703 entry, each carrying the lot code.", "• A cake is taken out of the run, without a tag, when it breaks at depanning, is plainly too big or too small after baking, or is oversoaked in the syrup. These are ordinary losses in production, not held product. Each is set aside from good product, counted, and included in the units not packed on FRM-520. The lot's retention sample may be taken from them - a cake that is too big or too small will do, an oversoaked one will not - or from good product. Whichever it is, the sample is soaked and sealed like the rest of the lot and logged on FRM-703. Cakes not kept as a sample leave as food waste under FSQM-037. The hold tag is for product whose safety or quality is in question, not for these.", "The lot code", "• The lot code is the last digit of the year and the three-digit day of the year on which the product was BAKED, for example 6272. It is the same code written on FRM-507 for that day's oven loads.", "• When wrapping runs into the next day, the coder is set to the bake day's code, not to the day of wrapping. A product baked on day 272 is 6272 whenever it is packed.", "• One lot is one product baked on one day. If the same product is baked on two days, it is two lots.", "The Production Lot Record - the cross reference", "• For each product baked each day, a Production Lot Record is kept on FRM-520 as the product is made - filled in directly in the Team Portal, or written on the printed prep sheet on the floor and entered within one working day (SQF 2.6.2.1 i).", "• The record carries the product, its lot code and the bake date, and a line for every ingredient used with the supplier lot printed on its container. If two lots of the same ingredient are used, both are written down.", "• Processing aids are listed like ingredients - in particular the pan spray, which contains soy - so that every allergen-bearing input can be traced back (SQF 2.8.1.8).", "• If rework is used, it is recorded with its own original lot code, so a lot made with rework traces back through the rework to its supplier lots (SQF 2.6.2.1 iii).", "• At wrapping, the record takes the pack date and the number of units packed. The film or vacuum bag touches the cake and is food-contact packaging: its lot is written when the maker prints one, and when none is printed the date that film was received is written instead, which FRM-301 ties to its supplier. The boxes the sealed cakes go into are outer packaging and are not traced (SQF 2.6.2.1 ii).", "• Whichever way it is filled in, the FRM-520 entry is the record. A photo of a paper prep sheet may be attached to it but is not required; a paper sheet that was used is kept with the batch records under SOP-2.2.3 (SQF 2.6.2.1).", "Start-up, changeover and the label", "> Every rum cake is packed in the same box. The ingredient list and the allergen statement are printed on that box and are the same for every flavor. What changes from one product to the next is what the coder prints on the box at packing: the company name, the flavor, the lot code, the best-by date and the bar code. Putting the right label on a product therefore means loading the right coder message.", "> Product wrapped in printed film - the biscotti - is different. Each variety has its own film, with its own ingredient list and allergen statement printed on it, and the coder adds only the lot code and the best-by date. There, putting the right label on the product means loading the right roll of film, and a wrong roll is a wrong allergen statement.", "• At the start of packing, and every time the product changes, the person packing loads the coder message for that product - and, where the product is wrapped in printed film, the roll for that variety - and makes one pack (SOP-603, SOP-604, SOP-605).", "• That first pack is checked against the Production Lot Record before packing carries on: the flavor or variety on the pack is the product being packed; on printed film, the film is the one for that variety, with its allergen statement; the lot code and best-by date are right; and any bar code scans. Production staff trained on the coder and the wrapper are authorized to approve it. The result and the name of the person who checked are written on FRM-520 (SQF 2.6.1.2, 2.8.1.9).", "• The check is made again whenever the coder is restarted or its message is edited, and whenever a new roll of film is loaded during the run.", "• Before the next product is packed, boxes already printed for the one before are taken off the packing table, the film of the variety before is taken off the wrapper and put back with its own kind, and any other packaging that belongs only to that product is removed (SQF 2.6.1.2).", "• No pre-printed label is issued by count, so what is reconciled is the product. The cakes are counted when they go on the baking rack. At the end of packing that count is compared with the units packed plus the units not packed - broken at depanning, the wrong size, oversoaked, otherwise rejected or damaged, or kept as the retention sample - and all three figures are written on FRM-520. A difference that cannot be explained is settled before the lot is released, and raised on FRM-007 if it cannot be (SQF 2.6.1.2).", "• Before packing ends, three finished packs from the lot are weighed, each one whole, on a scale that is in the calibration program (FSQM-030), and the three weights are written on FRM-520 with the net weight on the label and the weight of the empty packaging. With the empty packaging taken off, their average is at or above the net weight on the label. If it is not, packing stops and the lot is held on FRM-702 until the SQF Practitioner decides (FSQM-020, SQF 2.4.1.1).", "• A product goes into a printed box or a printed film only if the ingredients and allergens of its formula are the ones printed on it. That is checked on FRM-601 before a new or changed product is first packed, and the change is assessed first under FSQM-007 (SQF 2.8.1.9).", "• When a printed box, a printed film or a coder message is replaced, the old boxes or film are taken out of use, counted and disposed of under FSQM-037, and the old message is deleted from the coder. Both are noted on the FRM-601 for the new version (SQF 2.8.1.9).", "• The label and the code are looked at once more, by the SQF Practitioner, when the lot is released on FRM-701.", "Tracing", "• One step back: from a finished lot code, FRM-520 gives every supplier lot used, and FRM-301 gives the supplier and the date each was received (SQF 2.6.2.1 i, ii).", "• One step forward: from a finished lot code, FRM-801 gives every customer who collected it, how much and when (SQF 2.6.2.1 i).", "• From a supplier lot - for example a supplier's recall or allergen notice - the FRM-520 entries that list it give every finished lot it went into, and FRM-801 gives where those lots went (SQF 2.8.1.8).", "Testing the trace", "• At least once a year, the SQF Practitioner picks a finished lot and traces it both ways from the records alone: back to every supplier lot and its receipt on FRM-301, and forward to every customer on FRM-801 (SQF 2.6.2.1 iv).", "• The test passes when every input is traced to a supplier lot and a receipt, and the quantity packed is accounted for - collected by customers, still on site, retained on FRM-703, or disposed of on FRM-702. Any gap is raised as a CAPA on FRM-007 under FSQM-009.", "• The trace test is part of the annual product recall and withdrawal test and is reviewed with it (SQF 2.6.2.1 iv).", "Records", "• FRM-301, FRM-520, FRM-507, FRM-701 and FRM-801 are the trace records. They are kept for at least two years, as SOP-2.2.3 requires (SQF 2.6.2.1)."]$c2$::jsonb;
  rec021_old constant jsonb := $c3$"• FRM-520 entries, one per product per bake day, carrying the first-box check and the count reconciliation; any paper prep sheets used, filed with the batch records\n• FRM-301 receiving entries\n• FRM-507, FRM-701 and FRM-801 entries carrying the lot code\n• The annual trace test"$c3$::jsonb;
  rec021_new constant jsonb := $c4$"• FRM-520 entries, one per product per bake day, carrying the first-box check, the count reconciliation and the three pack weights; any paper prep sheets used, filed with the batch records\n• FRM-301 receiving entries\n• FRM-507, FRM-701 and FRM-801 entries carrying the lot code\n• The annual trace test"$c4$::jsonb;
  h021_old constant jsonb := $c5$"New - 2026-09-29 - DRAFT under D-20, for the three Minor findings against 2.6.1.1, 2.6.2.1 and 2.8.1.8. Written as one program; the workbook's separate SOP-2.6.2 is not needed.\n\nWHAT THE SITE DOES (owner, 2026-09-29): the lot code is the last digit of the year and the day of the year, e.g. 6272, as SOP-2.2.3 already states; it is the BAKE day. Ingredients are weighed out of the bags and containers they arrived in; nothing is decanted. All product goes to business customers and is collected. Supplier lots are recorded at receipt on FRM-301 and the lot and customer at dispatch on FRM-801.\n\nNEW WITH THIS PROGRAM: the Production Lot Record, FRM-520 - filled in directly in the Team Portal or from the printed prep sheet - which is the cross reference between the supplier lots used and our lot code. Before this, nothing recorded which supplier lots went into which lot. Also new: the coder is set to the bake day when wrapping runs into the next day, and the annual trace test.\n\nTHE TRACE TEST'S RECORD arrives with the recall and withdrawal program (D-21), as 2.6.2.1 iv ties the two together; the 'traceability test' row on the verification schedule stays planned until then.\n\nTO CONFIRM BEFORE ISSUE: (1) the rack card for baked product cooling on racks - product and lot code; (2) how syrup made ahead is identified while stored - open under D-14; (3) whether the coder is set to the bake day today when wrapping runs over, or whether that is new practice.\n\nRENUMBERED 2026-09-30: the Production Lot Record is FRM-520, not FRM-510, so it is not mistaken for FRM-501 Formula Sheet & Batch Data.\n\nPAPER OPTIONAL 2026-09-30 (owner): the site will not be forced onto paper. FRM-520 can be filled in directly; the printed prep sheet is an option, and a photo of it may be attached but is not required. The required 'Paper sheet - photo attached' question was removed from FRM-520.\n\nCHANGEOVER AND LABEL CONTROL ADDED 2026-10-06 (still a draft), for what D-17 left open: 2.6.1.2 and 2.8.1.9. Written into this program and FRM-520, with no new document and no new form.\n\nWHAT THE SITE DOES (owner, 2026-10-06): every rum cake goes into the same box, with one printed ingredient list and allergen statement for all flavors. An ink-jet coder prints the company name, flavor, lot code, best-by date and bar code on the box just after the cake goes in, so there is no stock of pre-printed labels to issue, clear or count. The first printed box is already looked at, but nothing was written down. The cakes are counted on the baking rack and the packed cakes are bulk packed 48 to a case, but the two counts were never compared. No artwork has changed yet, so there has been no obsolete packaging.\n\nNEW WITH THIS CHANGE: the first-box check is recorded on FRM-520 with who made it; the rack count, the units packed and the units not packed are written on FRM-520 and compared; the rule that a product may only go into the printed box if its formula matches what is printed on it; and what happens to old boxes and coder messages when artwork changes.\n\nONE PERSON PACKS. The program does not pretend there is a separate supervisor: production staff trained on the coder approve the first box, and the SQF Practitioner sees the label and code again at release on FRM-701.\n\nTO CONFIRM BEFORE ISSUE: (4) that every flavor's formula matches the one ingredient list and allergen statement printed on the box - an FRM-601 review per flavor; (5) how products packed in another customer's packaging are labelled, and whether the same first-box check applies to them.\n\nORDINARY LOSSES 2026-10-06 (owner and SQF Practitioner): a cake often breaks into pieces at depanning; a cake that is plainly too big or too small after baking is removed; and a cake oversoaked at dunking is removed. They are set aside and counted as waste; tagging each one on FRM-702 is not reasonable and was never the intent. The retention sample MAY be one of them (an off-size cake, never an oversoaked one) or a good cake - it is a choice, not a rule - and is soaked and sealed like the rest of the lot either way; cakes not kept leave as food waste. The line that said rejected product is identified by a hold tag now covers held product and retention samples only, and a new line says these ordinary losses is counted as not packed on FRM-520 and leaves as food waste. FRM-520's 'Not packed' help line names them.\n\nPRINTED FILM 2026-10-06 (owner). The two points listed to confirm are answered. (4) Every rum cake flavor's formula matches the one ingredient list printed on the box. (5) The only other product packed here is the biscotti, which is baked on site and flow-wrapped in printed film: each variety has its own film carrying everything but the lot code and best-by date, which the coder prints. The first pack is already looked at, unrecorded. The Part now covers printed film: the roll for the variety is part of the first-pack check, the check is repeated when a new roll is loaded, and the previous variety's film comes off the wrapper at changeover. Old packaging is 'disposed of under FSQM-037', not 'destroyed', because that program decides which printed packaging has to be defaced.\n\nISSUED 2026-10-06, with FRM-520. What the draft listed to confirm (owner, 2026-10-06): (1) RACK CARD - a card with the product and lot code is used on racks of cooling product, as written. (2) SYRUP - syrup made ahead is kept in a labelled container; a line saying so is added under Identification at every stage. (3) CODER - when wrapping runs into the next day the coder is set to the bake day's code, as written. (4) and (5) were answered the same day and are recorded above. The record of the annual trace test arrives with the recall and withdrawal program, so the 'traceability test' row on the verification schedule stays planned until that program is issued."$c5$::jsonb;
  h021_new constant jsonb := $c6$"New - 2026-09-29 - DRAFT under D-20, for the three Minor findings against 2.6.1.1, 2.6.2.1 and 2.8.1.8. Written as one program; the workbook's separate SOP-2.6.2 is not needed.\n\nWHAT THE SITE DOES (owner, 2026-09-29): the lot code is the last digit of the year and the day of the year, e.g. 6272, as SOP-2.2.3 already states; it is the BAKE day. Ingredients are weighed out of the bags and containers they arrived in; nothing is decanted. All product goes to business customers and is collected. Supplier lots are recorded at receipt on FRM-301 and the lot and customer at dispatch on FRM-801.\n\nNEW WITH THIS PROGRAM: the Production Lot Record, FRM-520 - filled in directly in the Team Portal or from the printed prep sheet - which is the cross reference between the supplier lots used and our lot code. Before this, nothing recorded which supplier lots went into which lot. Also new: the coder is set to the bake day when wrapping runs into the next day, and the annual trace test.\n\nTHE TRACE TEST'S RECORD arrives with the recall and withdrawal program (D-21), as 2.6.2.1 iv ties the two together; the 'traceability test' row on the verification schedule stays planned until then.\n\nTO CONFIRM BEFORE ISSUE: (1) the rack card for baked product cooling on racks - product and lot code; (2) how syrup made ahead is identified while stored - open under D-14; (3) whether the coder is set to the bake day today when wrapping runs over, or whether that is new practice.\n\nRENUMBERED 2026-09-30: the Production Lot Record is FRM-520, not FRM-510, so it is not mistaken for FRM-501 Formula Sheet & Batch Data.\n\nPAPER OPTIONAL 2026-09-30 (owner): the site will not be forced onto paper. FRM-520 can be filled in directly; the printed prep sheet is an option, and a photo of it may be attached but is not required. The required 'Paper sheet - photo attached' question was removed from FRM-520.\n\nCHANGEOVER AND LABEL CONTROL ADDED 2026-10-06 (still a draft), for what D-17 left open: 2.6.1.2 and 2.8.1.9. Written into this program and FRM-520, with no new document and no new form.\n\nWHAT THE SITE DOES (owner, 2026-10-06): every rum cake goes into the same box, with one printed ingredient list and allergen statement for all flavors. An ink-jet coder prints the company name, flavor, lot code, best-by date and bar code on the box just after the cake goes in, so there is no stock of pre-printed labels to issue, clear or count. The first printed box is already looked at, but nothing was written down. The cakes are counted on the baking rack and the packed cakes are bulk packed 48 to a case, but the two counts were never compared. No artwork has changed yet, so there has been no obsolete packaging.\n\nNEW WITH THIS CHANGE: the first-box check is recorded on FRM-520 with who made it; the rack count, the units packed and the units not packed are written on FRM-520 and compared; the rule that a product may only go into the printed box if its formula matches what is printed on it; and what happens to old boxes and coder messages when artwork changes.\n\nONE PERSON PACKS. The program does not pretend there is a separate supervisor: production staff trained on the coder approve the first box, and the SQF Practitioner sees the label and code again at release on FRM-701.\n\nTO CONFIRM BEFORE ISSUE: (4) that every flavor's formula matches the one ingredient list and allergen statement printed on the box - an FRM-601 review per flavor; (5) how products packed in another customer's packaging are labelled, and whether the same first-box check applies to them.\n\nORDINARY LOSSES 2026-10-06 (owner and SQF Practitioner): a cake often breaks into pieces at depanning; a cake that is plainly too big or too small after baking is removed; and a cake oversoaked at dunking is removed. They are set aside and counted as waste; tagging each one on FRM-702 is not reasonable and was never the intent. The retention sample MAY be one of them (an off-size cake, never an oversoaked one) or a good cake - it is a choice, not a rule - and is soaked and sealed like the rest of the lot either way; cakes not kept leave as food waste. The line that said rejected product is identified by a hold tag now covers held product and retention samples only, and a new line says these ordinary losses is counted as not packed on FRM-520 and leaves as food waste. FRM-520's 'Not packed' help line names them.\n\nPRINTED FILM 2026-10-06 (owner). The two points listed to confirm are answered. (4) Every rum cake flavor's formula matches the one ingredient list printed on the box. (5) The only other product packed here is the biscotti, which is baked on site and flow-wrapped in printed film: each variety has its own film carrying everything but the lot code and best-by date, which the coder prints. The first pack is already looked at, unrecorded. The Part now covers printed film: the roll for the variety is part of the first-pack check, the check is repeated when a new roll is loaded, and the previous variety's film comes off the wrapper at changeover. Old packaging is 'disposed of under FSQM-037', not 'destroyed', because that program decides which printed packaging has to be defaced.\n\nISSUED 2026-10-06, with FRM-520. What the draft listed to confirm (owner, 2026-10-06): (1) RACK CARD - a card with the product and lot code is used on racks of cooling product, as written. (2) SYRUP - syrup made ahead is kept in a labelled container; a line saying so is added under Identification at every stage. (3) CODER - when wrapping runs into the next day the coder is set to the bake day's code, as written. (4) and (5) were answered the same day and are recorded above. The record of the annual trace test arrives with the recall and withdrawal program, so the 'traceability test' row on the verification schedule stays planned until that program is issued.\n\nv2 - 2026-10-12 - Three finished packs are weighed at packing. Approved GJM.\n\nThe Part 'Start-up, changeover and the label' gains one line: before packing ends, three finished packs are weighed and the weights written on FRM-520 (v2), with the lot held on FRM-702 if their average net weight is below the label. The weighing was done at release until now (FSQM-020 v4; owner's decision, 2026-10-12). Records names the pack weights. Nothing else changes."$c6$::jsonb;
begin
  -- ---- FRM-520
  select count(*) into n from public.sop_documents where sop_number = 'FRM-520' and status = 'active';
  if n <> 1 then raise exception 'FRM-520: expected one active document, found %', n; end if;
  select * into d from public.sop_documents where sop_number = 'FRM-520' and status = 'active';
  if d.revision = 'v2' and d.content->'form_schema'->'sections'->2 = sec_new and d.content->'revision_history' = h520 then
    raise notice 'FRM-520: already at v2 as intended, left alone';
  elsif d.revision <> 'New' or d.content->'form_schema'->'sections'->2 is distinct from sec_old
     or coalesce(d.content->'revision_history', 'null'::jsonb) <> 'null'::jsonb then
    raise exception 'FRM-520 is not the form this migration was written against';
  else
    update public.sop_documents
       set content = jsonb_set(jsonb_set(content, '{form_schema,sections,2}', sec_new), '{revision_history}', h520),
           revision = 'v2', effective_date = '2026-10-12', approved_by = 'GJM'
     where id = d.id;
  end if;

  -- ---- FSQM-020
  select count(*) into n from public.sop_documents where sop_number = 'FSQM-020' and status = 'active';
  if n <> 1 then raise exception 'FSQM-020: expected one active document, found %', n; end if;
  select * into d from public.sop_documents where sop_number = 'FSQM-020' and status = 'active';
  if d.revision = 'v4' and d.content->'procedure' = p020_new and d.content->'form_references' = refs020_new
     and d.content->'records' = rec020_new and d.content->'revision_history' = h020_new then
    raise notice 'FSQM-020: already at v4 as intended, left alone';
  elsif d.revision <> 'v3' or d.content->'procedure' is distinct from p020_old or d.content->'form_references' is distinct from refs020_old
     or d.content->'records' is distinct from rec020_old or d.content->'revision_history' is distinct from h020_old then
    raise exception 'FSQM-020 is not the document this migration was written against';
  else
    update public.sop_documents
       set content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{procedure}', p020_new), '{form_references}', refs020_new),
                     '{records}', rec020_new), '{revision_history}', h020_new),
           revision = 'v4', effective_date = '2026-10-12', approved_by = 'GJM'
     where id = d.id;
  end if;

  -- ---- FSQM-021
  select count(*) into n from public.sop_documents where sop_number = 'FSQM-021' and status = 'active';
  if n <> 1 then raise exception 'FSQM-021: expected one active document, found %', n; end if;
  select * into d from public.sop_documents where sop_number = 'FSQM-021' and status = 'active';
  if d.revision = 'v2' and d.content->'procedure' = p021_new and d.content->'records' = rec021_new and d.content->'revision_history' = h021_new then
    raise notice 'FSQM-021: already at v2 as intended, left alone';
  elsif d.revision <> 'New' or d.content->'procedure' is distinct from p021_old or d.content->'records' is distinct from rec021_old
     or d.content->'revision_history' is distinct from h021_old then
    raise exception 'FSQM-021 is not the document this migration was written against';
  else
    update public.sop_documents
       set content = jsonb_set(jsonb_set(jsonb_set(content, '{procedure}', p021_new), '{records}', rec021_new), '{revision_history}', h021_new),
           revision = 'v2', effective_date = '2026-10-12', approved_by = 'GJM'
     where id = d.id;
  end if;
end $$;
